<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/profile-commerce-refund-requests-v1100.php';
require_permission('account.access');
$pdo=db();$user=current_user();if(!$pdo||!$user)redirect(url('/login.php'));if(!agent_commerce_schema_ready_v800($pdo))redirect(url('/upgrade.php'));
$uid=(int)$user['id'];$error='';$notice=trim((string)($_GET['saved']??''));
function profile_commerce_refund_requests_redirect_v1100(string $message): never{redirect(url('/profile-commerce-refund-requests.php?saved='.rawurlencode($message)));}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf())$error='Session expired. Please try again.';
    else try{
        $action=(string)($_POST['action']??'');$orderId=max(0,(int)($_POST['order_id']??0));
        if($action==='approve'){profile_commerce_owner_approve_refund_request_v1100($pdo,$uid,$orderId,$user);profile_commerce_refund_requests_redirect_v1100('Refund submitted to the original payment provider.');}
        if($action==='decline'){profile_commerce_owner_decline_refund_request_v1100($pdo,$uid,$orderId);profile_commerce_refund_requests_redirect_v1100('Customer refund request declined.');}
        throw new RuntimeException('Unknown refund request action.');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$requests=profile_commerce_refund_requests_for_owner_v1100($pdo,$uid,100);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(system_agent_name())?> | Refund Requests</title><link rel="stylesheet" href="<?=e(url('/chat.css?v=82'))?>"><style>
.prr-main{background:#f7f7f5;min-height:100vh}.prr-canvas{padding:30px}.prr-inner{max-width:1050px;margin:auto}.prr-card{background:#fff;border:1px solid #e3e4df;border-radius:20px;padding:20px;margin-bottom:14px}.prr-eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:#72736e}.prr-muted{color:#6f716b}.prr-tags{display:flex;gap:6px;flex-wrap:wrap}.prr-tag{padding:4px 8px;border-radius:999px;background:#f0f1ed;font-size:12px}.prr-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.prr-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid #cfd1ca;border-radius:10px;padding:9px 12px;background:#fff;color:#111;cursor:pointer}.prr-btn.primary{background:#111;color:#fff;border-color:#111}.prr-btn.danger{color:#8c241d}.prr-notice{padding:12px 14px;border-radius:12px;margin:12px 0;background:#eaf7ee}.prr-notice.err{background:#fff0ee;color:#86251f}.prr-reason{padding:14px;background:#f8f8f5;border-radius:12px;white-space:pre-wrap}.prr-row{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}@media(max-width:700px){.prr-canvas{padding:18px}.prr-row{display:block}}
</style></head><body><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='profile_commerce';require __DIR__.'/includes/workspace-sidebar-v82.php';?><div class="chat-sidebar-backdrop" id="chatSidebarBackdrop"></div><main class="chat-main prr-main"><?php $memberHeaderUser=$user;$memberHeaderTitle='Refund Requests';$memberHeaderSubtitle='Customer requests require your explicit review before money moves';$memberHeaderActions='<a class="prr-btn" href="'.e(url('/profile-commerce-products.php')).'">Profile Commerce</a>';require __DIR__.'/includes/member-header.php';?><section class="prr-canvas"><div class="prr-inner"><div><span class="prr-eyebrow">Phase 11 · Customer lifecycle</span><h1>Customer refund requests</h1><p class="prr-muted">Requests are recorded on the canonical Profile Commerce order. Approving here reuses the Phase 8 audited provider-neutral refund engine; declining does not move money.</p></div><?php if($notice!==''):?><div class="prr-notice"><?=e($notice)?></div><?php endif;?><?php if($error!==''):?><div class="prr-notice err" role="alert"><?=e($error)?></div><?php endif;?><?php if(!$requests):?><section class="prr-card"><p class="prr-muted">No customer refund requests yet.</p></section><?php endif;?><?php foreach($requests as $order):$request=$order['refund_request'];$items=(array)($order['items']??[]);$item=$items[0]??[];$remaining=max(0,(int)$order['amount_paid_cents']-(int)$order['amount_refunded_cents']);?><section class="prr-card"><div class="prr-row"><div><div class="prr-tags"><span class="prr-tag"><?=e((string)$request['status'])?></span><span class="prr-tag"><?=e((string)$order['payment_status'])?></span></div><h2><?=e((string)($item['title_snapshot']??$order['order_number']))?></h2><p class="prr-muted"><?=e((string)$order['order_number'])?> · <?=e(agent_commerce_money_v800($remaining,(string)$order['currency']))?> refundable<?php if(trim((string)$order['payer_email'])!==''):?> · <?=e((string)$order['payer_email'])?><?php endif;?></p></div><small class="prr-muted"><?=e((string)$request['requested_at'])?></small></div><div class="prr-reason"><?=e((string)$request['reason'])?></div><?php if((string)$request['status']==='pending'):?><div class="prr-actions"><form method="post" onsubmit="return confirm('Approve this customer refund and send it to the original payment provider?')"><?=csrf_field()?><input type="hidden" name="action" value="approve"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button class="prr-btn primary" type="submit">Approve refund</button></form><form method="post" onsubmit="return confirm('Decline this customer refund request?')"><?=csrf_field()?><input type="hidden" name="action" value="decline"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button class="prr-btn danger" type="submit">Decline request</button></form></div><?php elseif((string)$request['resolved_at']!==''):?><p class="prr-muted">Resolved <?=e((string)$request['resolved_at'])?></p><?php endif;?></section><?php endforeach;?></div></section></main></div><script src="<?=e(url('/chat-shell-v82.js'))?>" defer></script></body></html>